arguments.cmd:
cd /app && cat > output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <meta name="color-scheme" content="light" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. Always free for patients." />

  <!-- Inter (Google Fonts) -->
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet" />

  <style>
    :root {
      /* Brand (OKLCH) */
      --brand-blue: oklch(56% 0.24 264);
      --brand-blue-2: oklch(63% 0.16 260);
      --brand-teal: oklch(70% 0.16 178);
      --brand-teal-2: oklch(62% 0.17 176);

      /* Neutrals */
      --bg: oklch(99% 0.01 255);
      --surface: oklch(98% 0.01 255);
      --surface-2: oklch(96% 0.01 255);
      --border: oklch(90% 0.015 255);
      --text: oklch(22% 0.02 255);
      --muted: oklch(45% 0.02 255);
      --muted-2: oklch(55% 0.02 255);

      /* Effects */
      --radius-sm: 12px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --shadow-sm: 0 10px 30px rgba(16, 24, 40, 0.08);
      --shadow-md: 0 18px 60px rgba(16, 24, 40, 0.12);
      --ring: 0 0 0 4px color-mix(in oklch, var(--brand-blue) 20%, transparent);

      /* Layout */
      --max: 1160px;
      --gutter: 20px;

      /* Motion */
      --ease: cubic-bezier(.2,.8,.2,1);
      --dur-1: 140ms;
      --dur-2: 220ms;
    }

    * { box-sizing: border-box; }
    html, body { height: 100%; }
    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
      color: var(--text);
      background: radial-gradient(1200px 500px at 10% 0%, color-mix(in oklch, var(--brand-blue) 12%, transparent) 0%, transparent 70%),
                  radial-gradient(900px 400px at 80% 10%, color-mix(in oklch, var(--brand-teal) 12%, transparent) 0%, transparent 65%),
                  var(--bg);
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a { color: inherit; text-decoration: none; }
    button, input, select { font: inherit; }

    .container {
      width: min(var(--max), calc(100% - (var(--gutter) * 2)));
      margin: 0 auto;
    }

    .skip-link {
      position: absolute;
      left: -999px;
      top: 12px;
      background: var(--surface);
      border: 1px solid var(--border);
      padding: 10px 12px;
      border-radius: 10px;
      box-shadow: var(--shadow-sm);
      z-index: 999;
    }
    .skip-link:focus { left: 12px; outline: none; box-shadow: var(--shadow-sm), var(--ring); }

    /* Header */
    .header {
      position: sticky;
      top: 0;
      z-index: 40;
      background: color-mix(in oklch, var(--bg) 85%, white);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
    }

    .header__inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 14px 0;
      gap: 16px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      letter-spacing: -0.03em;
    }

    .brand__mark {
      width: 38px;
      height: 38px;
      border-radius: 12px;
      display: grid;
      place-items: center;
      background: linear-gradient(135deg, var(--brand-blue), color-mix(in oklch, var(--brand-blue) 55%, var(--brand-teal)));
      box-shadow: 0 10px 30px rgba(0, 102, 255, 0.20);
    }
    .brand__mark svg { width: 22px; height: 22px; }

    .nav {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .nav__links {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .link {
      padding: 10px 12px;
      border-radius: 10px;
      color: var(--muted);
      font-weight: 600;
      transition: background var(--dur-1) var(--ease), color var(--dur-1) var(--ease);
    }
    .link:hover { background: color-mix(in oklch, var(--surface-2) 80%, transparent); color: var(--text); }

    .actions { display: flex; align-items: center; gap: 10px; }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      padding: 12px 14px;
      border-radius: 12px;
      border: 1px solid var(--border);
      background: var(--surface);
      color: var(--text);
      font-weight: 700;
      cursor: pointer;
      transition: transform var(--dur-1) var(--ease), box-shadow var(--dur-1) var(--ease), background var(--dur-1) var(--ease), border-color var(--dur-1) var(--ease);
      user-select: none;
    }
    .btn:hover { transform: translateY(-1px); box-shadow: var(--shadow-sm); }
    .btn:active { transform: translateY(0px); box-shadow: none; }

    .btn--primary {
      background: linear-gradient(180deg, color-mix(in oklch, var(--brand-blue) 92%, white) 0%, var(--brand-blue) 100%);
      border-color: color-mix(in oklch, var(--brand-blue) 70%, var(--border));
      color: white;
      box-shadow: 0 14px 40px rgba(0, 102, 255, 0.22);
    }
    .btn--primary:hover { box-shadow: 0 18px 60px rgba(0, 102, 255, 0.26); }

    .btn--cta {
      background: linear-gradient(180deg, color-mix(in oklch, var(--brand-teal) 88%, white) 0%, var(--brand-teal-2) 100%);
      border-color: color-mix(in oklch, var(--brand-teal-2) 70%, var(--border));
      color: oklch(16% 0.02 175);
      box-shadow: 0 14px 40px rgba(0, 186, 158, 0.18);
    }

    .btn--ghost {
      background: transparent;
      border-color: color-mix(in oklch, var(--border) 60%, transparent);
      color: var(--text);
    }

    .btn:focus-visible, .link:focus-visible, input:focus-visible, select:focus-visible {
      outline: none;
      box-shadow: var(--ring);
    }

    /* Mobile menu */
    .hamburger {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      border: 1px solid var(--border);
      background: var(--surface);
      display: none;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      transition: transform var(--dur-1) var(--ease), box-shadow var(--dur-1) var(--ease);
    }
    .hamburger:hover { transform: translateY(-1px); box-shadow: var(--shadow-sm); }

    .drawer-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(10, 20, 35, 0.40);
      opacity: 0;
      pointer-events: none;
      transition: opacity var(--dur-2) var(--ease);
      z-index: 60;
    }

    .drawer {
      position: fixed;
      right: 0;
      top: 0;
      height: 100%;
      width: min(360px, calc(100% - 48px));
      background: color-mix(in oklch, var(--surface) 92%, white);
      border-left: 1px solid var(--border);
      box-shadow: var(--shadow-md);
      transform: translateX(110%);
      transition: transform var(--dur-2) var(--ease);
      z-index: 70;
      padding: 18px;
      display: flex;
      flex-direction: column;
      gap: 14px;
    }

    body.drawer-open .drawer-backdrop { opacity: 1; pointer-events: auto; }
    body.drawer-open .drawer { transform: translateX(0); }

    .drawer__top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }

    .drawer__links { display: grid; gap: 6px; }
    .drawer__links a {
      padding: 12px 12px;
      border-radius: 12px;
      border: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
      background: color-mix(in oklch, var(--surface-2) 65%, transparent);
      font-weight: 700;
      transition: transform var(--dur-1) var(--ease);
    }
    .drawer__links a:hover { transform: translateY(-1px); }

    /* Hero */
    .hero {
      padding: 36px 0 28px;
    }

    .hero__grid {
      display: grid;
      grid-template-columns: 1.2fr 0.8fr;
      gap: 28px;
      align-items: start;
    }

    .badge {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 8px 12px;
      border-radius: 999px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: color-mix(in oklch, var(--surface) 92%, white);
      color: var(--muted);
      font-weight: 700;
      font-size: 13px;
    }

    .badge svg { width: 16px; height: 16px; }

    h1 {
      font-size: clamp(34px, 4vw, 52px);
      letter-spacing: -0.045em;
      line-height: 1.03;
      margin: 14px 0 12px;
    }

    .lede {
      font-size: 18px;
      color: var(--muted);
      margin: 0 0 18px;
      max-width: 56ch;
    }

    .hero__cta {
      display: flex;
      gap: 10px;
      align-items: center;
      flex-wrap: wrap;
      margin: 8px 0 16px;
    }

    .trust {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      align-items: center;
      color: var(--muted);
      font-weight: 600;
      font-size: 14px;
    }

    .trust .chip {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 10px;
      background: color-mix(in oklch, var(--surface) 90%, white);
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      border-radius: 999px;
    }

    /* Hero illustration */
    .hero-art {
      position: relative;
      border-radius: var(--radius-lg);
      background: linear-gradient(135deg,
        color-mix(in oklch, var(--brand-blue) 18%, white) 0%,
        color-mix(in oklch, var(--brand-teal) 16%, white) 60%,
        color-mix(in oklch, var(--surface) 92%, white) 100%);
      border: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
      box-shadow: var(--shadow-md);
      overflow: hidden;
      padding: 18px;
      min-height: 360px;
    }

    .hero-art__grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 10px;
      align-content: start;
      height: 100%;
    }

    .mini-card {
      border-radius: 18px;
      background: color-mix(in oklch, var(--surface) 92%, white);
      border: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
      padding: 12px;
      box-shadow: var(--shadow-sm);
      transform: translateZ(0);
      transition: transform var(--dur-2) var(--ease);
    }
    .mini-card:hover { transform: translateY(-2px); }

    .mini-card__top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
    .mini-card__name { font-weight: 800; letter-spacing: -0.02em; }
    .mini-card__meta { color: var(--muted); font-weight: 600; font-size: 13px; margin-top: 6px; }

    .rating {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 8px 10px;
      border-radius: 999px;
      background: color-mix(in oklch, var(--brand-teal) 22%, white);
      border: 1px solid color-mix(in oklch, var(--brand-teal) 28%, var(--border));
      font-weight: 800;
      font-size: 13px;
      color: oklch(18% 0.02 175);
      white-space: nowrap;
    }

    .pill {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 10px;
      border-radius: 999px;
      background: color-mix(in oklch, var(--brand-blue) 18%, white);
      border: 1px solid color-mix(in oklch, var(--brand-blue) 24%, var(--border));
      font-weight: 800;
      font-size: 13px;
      color: color-mix(in oklch, var(--brand-blue) 85%, oklch(20% 0.02 255));
    }

    .hero-art__bg {
      position: absolute;
      inset: -20px;
      pointer-events: none;
      opacity: 0.55;
      background-image:
        radial-gradient(circle at 20% 20%, rgba(0,102,255,0.18) 0%, transparent 35%),
        radial-gradient(circle at 80% 30%, rgba(0,186,158,0.16) 0%, transparent 40%),
        radial-gradient(circle at 35% 80%, rgba(0,102,255,0.12) 0%, transparent 45%);
      filter: blur(0px);
    }

    /* Search */
    .search-wrap {
      margin-top: 16px;
      border-radius: 22px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: color-mix(in oklch, var(--surface) 92%, white);
      box-shadow: var(--shadow-md);
      padding: 14px;
    }

    .search-title {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      margin-bottom: 12px;
    }

    .search-title h2 {
      margin: 0;
      font-size: 16px;
      letter-spacing: -0.02em;
    }

    .search-title .hint {
      color: var(--muted);
      font-size: 13px;
      font-weight: 600;
    }

    .search {
      display: grid;
      grid-template-columns: 1.4fr 1fr 0.9fr auto;
      gap: 10px;
      align-items: stretch;
    }

    .field {
      position: relative;
      border-radius: 16px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: white;
      padding: 10px 12px;
      display: flex;
      gap: 10px;
      align-items: center;
      min-height: 54px;
      transition: box-shadow var(--dur-1) var(--ease), border-color var(--dur-1) var(--ease);
    }

    .field:focus-within {
      border-color: color-mix(in oklch, var(--brand-blue) 65%, var(--border));
      box-shadow: var(--ring);
    }

    .field svg { width: 18px; height: 18px; color: color-mix(in oklch, var(--muted) 70%, var(--text)); }

    .field label {
      position: absolute;
      top: 8px;
      left: 44px;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: color-mix(in oklch, var(--muted) 70%, var(--text));
    }

    .control {
      width: 100%;
      border: none;
      outline: none;
      background: transparent;
      padding: 18px 0 0 0;
      color: var(--text);
      font-weight: 650;
    }

    .control::placeholder { color: color-mix(in oklch, var(--muted) 70%, white); }

    .geo {
      margin-left: auto;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: color-mix(in oklch, var(--surface-2) 65%, transparent);
      padding: 8px 10px;
      border-radius: 999px;
      font-weight: 800;
      font-size: 12px;
      color: var(--text);
      cursor: pointer;
      transition: transform var(--dur-1) var(--ease), box-shadow var(--dur-1) var(--ease);
      white-space: nowrap;
    }
    .geo:hover { transform: translateY(-1px); box-shadow: var(--shadow-sm); }

    .search .btn--submit {
      border-radius: 16px;
      min-height: 54px;
      padding: 12px 16px;
    }

    /* Autocomplete dropdown */
    .ac {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      right: 0;
      border-radius: 16px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: color-mix(in oklch, var(--surface) 92%, white);
      box-shadow: var(--shadow-md);
      overflow: hidden;
      z-index: 30;
      opacity: 0;
      transform: translateY(-6px);
      pointer-events: none;
      transition: opacity var(--dur-2) var(--ease), transform var(--dur-2) var(--ease);
    }

    .ac[data-open="true"] {
      opacity: 1;
      transform: translateY(0);
      pointer-events: auto;
    }

    .ac__header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 10px 12px;
      border-bottom: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
      color: var(--muted);
      font-size: 12px;
      font-weight: 700;
    }

    .ac__list { max-height: 260px; overflow: auto; }

    .ac__item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 12px 12px;
      cursor: pointer;
      transition: background var(--dur-1) var(--ease);
    }

    .ac__item:hover, .ac__item[aria-selected="true"] {
      background: color-mix(in oklch, var(--brand-blue) 10%, white);
    }

    .ac__main { display: flex; flex-direction: column; gap: 2px; }
    .ac__title { font-weight: 800; letter-spacing: -0.02em; }
    .ac__sub { color: var(--muted); font-size: 12px; font-weight: 650; }

    .kbd {
      font-size: 12px;
      font-weight: 800;
      color: var(--muted);
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: color-mix(in oklch, var(--surface-2) 70%, transparent);
      border-radius: 8px;
      padding: 4px 8px;
      white-space: nowrap;
    }

    /* Sections */
    section {
      padding: 54px 0;
    }

    .section-head {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 18px;
      margin-bottom: 22px;
    }

    .section-head h2 {
      margin: 0;
      font-size: 28px;
      letter-spacing: -0.035em;
    }

    .section-head p {
      margin: 0;
      color: var(--muted);
      font-weight: 600;
      max-width: 60ch;
    }

    .muted { color: var(--muted); }

    /* Specialties */
    .specialties {
      background: color-mix(in oklch, var(--surface-2) 55%, white);
      border-top: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
      border-bottom: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
    }

    .cards {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px;
    }

    .card {
      border-radius: 18px;
      background: color-mix(in oklch, var(--surface) 92%, white);
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      padding: 16px;
      box-shadow: var(--shadow-sm);
      transition: transform var(--dur-1) var(--ease), box-shadow var(--dur-1) var(--ease);
      cursor: pointer;
      display: flex;
      gap: 12px;
      align-items: center;
      min-height: 74px;
    }

    .card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

    .icon {
      width: 46px;
      height: 46px;
      border-radius: 16px;
      background: linear-gradient(135deg,
        color-mix(in oklch, var(--brand-blue) 15%, white) 0%,
        color-mix(in oklch, var(--brand-teal) 14%, white) 100%);
      border: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
      display: grid;
      place-items: center;
      flex: 0 0 auto;
    }

    .icon svg { width: 22px; height: 22px; color: color-mix(in oklch, var(--brand-blue) 72%, oklch(24% 0.02 255)); }

    .card__title { font-weight: 850; letter-spacing: -0.02em; }
    .card__desc { color: var(--muted); font-weight: 600; font-size: 13px; margin-top: 2px; }

    /* Stats */
    .stats {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 12px;
      margin-top: 18px;
    }

    .stat {
      border-radius: 18px;
      background: linear-gradient(180deg, color-mix(in oklch, var(--surface) 92%, white) 0%, white 100%);
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      padding: 16px;
      box-shadow: var(--shadow-sm);
    }

    .stat__num {
      font-size: 24px;
      font-weight: 900;
      letter-spacing: -0.03em;
      margin: 0;
      color: color-mix(in oklch, var(--brand-blue) 84%, oklch(20% 0.02 255));
    }

    .stat__label {
      margin: 8px 0 0;
      color: var(--muted);
      font-weight: 650;
    }

    /* How it works */
    .steps {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px;
      margin-top: 10px;
    }

    .step {
      border-radius: 18px;
      background: color-mix(in oklch, var(--surface) 92%, white);
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      padding: 18px;
      box-shadow: var(--shadow-sm);
      position: relative;
      overflow: hidden;
    }

    .step::before {
      content: "";
      position: absolute;
      inset: -40px -40px auto auto;
      width: 180px;
      height: 180px;
      background: radial-gradient(circle at 30% 30%, color-mix(in oklch, var(--brand-teal) 22%, transparent) 0%, transparent 60%);
      transform: rotate(10deg);
      pointer-events: none;
    }

    .step__num {
      width: 40px;
      height: 40px;
      border-radius: 14px;
      display: grid;
      place-items: center;
      font-weight: 900;
      background: color-mix(in oklch, var(--brand-blue) 16%, white);
      border: 1px solid color-mix(in oklch, var(--brand-blue) 20%, var(--border));
      color: color-mix(in oklch, var(--brand-blue) 85%, oklch(20% 0.02 255));
    }

    .step h3 {
      margin: 14px 0 8px;
      font-size: 18px;
      letter-spacing: -0.02em;
    }

    .step p {
      margin: 0;
      color: var(--muted);
      font-weight: 600;
    }

    /* Testimonials */
    .testimonials {
      background: color-mix(in oklch, var(--surface-2) 45%, white);
      border-top: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
      border-bottom: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
    }

    .quotes {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px;
      margin-top: 10px;
    }

    .quote {
      border-radius: 18px;
      background: color-mix(in oklch, var(--surface) 92%, white);
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      padding: 18px;
      box-shadow: var(--shadow-sm);
    }

    .quote p {
      margin: 0;
      color: var(--text);
      font-weight: 650;
      letter-spacing: -0.01em;
    }

    .quote .who {
      margin-top: 14px;
      color: var(--muted);
      font-weight: 750;
    }

    .quote .who strong {
      color: var(--text);
      font-weight: 900;
    }

    /* App promo */
    .app {
      padding: 58px 0;
    }

    .app__panel {
      border-radius: 26px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: linear-gradient(135deg,
        color-mix(in oklch, var(--brand-blue) 12%, white) 0%,
        color-mix(in oklch, var(--brand-teal) 12%, white) 70%,
        color-mix(in oklch, var(--surface) 92%, white) 100%);
      box-shadow: var(--shadow-md);
      padding: 22px;
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      gap: 18px;
      align-items: center;
      overflow: hidden;
      position: relative;
    }

    .app__panel::before {
      content: "";
      position: absolute;
      inset: -80px;
      background-image:
        radial-gradient(circle at 20% 25%, rgba(0,102,255,0.14) 0%, transparent 35%),
        radial-gradient(circle at 75% 30%, rgba(0,186,158,0.14) 0%, transparent 40%),
        radial-gradient(circle at 50% 80%, rgba(0,102,255,0.10) 0%, transparent 45%);
      pointer-events: none;
    }

    .app__copy { position: relative; }

    .app__copy h2 {
      margin: 0;
      font-size: 30px;
      letter-spacing: -0.04em;
    }

    .app__copy p {
      margin: 10px 0 14px;
      color: var(--muted);
      font-weight: 650;
      max-width: 60ch;
    }

    .feature-list {
      list-style: none;
      padding: 0;
      margin: 0;
      display: grid;
      gap: 10px;
    }

    .feature {
      display: flex;
      gap: 10px;
      align-items: flex-start;
      color: var(--text);
      font-weight: 650;
    }

    .check {
      width: 22px;
      height: 22px;
      border-radius: 8px;
      background: color-mix(in oklch, var(--brand-teal) 25%, white);
      border: 1px solid color-mix(in oklch, var(--brand-teal) 28%, var(--border));
      display: grid;
      place-items: center;
      flex: 0 0 auto;
      margin-top: 1px;
    }
    .check svg { width: 14px; height: 14px; color: color-mix(in oklch, var(--brand-teal-2) 80%, oklch(20% 0.02 175)); }

    .stores {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-top: 16px;
    }

    .store {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 12px 14px;
      border-radius: 14px;
      background: color-mix(in oklch, var(--surface) 92%, white);
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      box-shadow: var(--shadow-sm);
      transition: transform var(--dur-1) var(--ease), box-shadow var(--dur-1) var(--ease);
      font-weight: 850;
    }
    .store:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }

    .store small { display: block; font-size: 11px; color: var(--muted); font-weight: 750; }

    .phone {
      position: relative;
      border-radius: 28px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: color-mix(in oklch, var(--surface) 92%, white);
      box-shadow: var(--shadow-md);
      padding: 14px;
      max-width: 360px;
      margin-left: auto;
      overflow: hidden;
    }

    .phone__screen {
      border-radius: 20px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: linear-gradient(180deg, white 0%, color-mix(in oklch, var(--surface-2) 65%, white) 100%);
      padding: 14px;
      min-height: 330px;
    }

    .phone__top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      margin-bottom: 12px;
    }

    .phone__pill {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 10px;
      border-radius: 999px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: color-mix(in oklch, var(--surface) 90%, white);
      font-weight: 900;
      letter-spacing: -0.02em;
      font-size: 12px;
      color: color-mix(in oklch, var(--brand-blue) 84%, oklch(18% 0.02 255));
    }

    .result {
      margin-top: 10px;
      border-radius: 16px;
      border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
      background: white;
      padding: 12px;
      display: grid;
      gap: 6px;
    }

    .result__row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
    .result__name { font-weight: 900; letter-spacing: -0.02em; }
    .result__meta { color: var(--muted); font-weight: 650; font-size: 12px; }

    /* Footer */
    footer {
      padding: 46px 0;
      color: var(--muted);
    }

    .footer {
      border-top: 1px solid color-mix(in oklch, var(--border) 65%, transparent);
      padding-top: 26px;
    }

    .footer__grid {
      display: grid;
      grid-template-columns: 1.1fr 1fr 1fr 1fr;
      gap: 18px;
    }

    .footer h3 {
      margin: 0 0 10px;
      font-size: 13px;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      color: color-mix(in oklch, var(--muted) 70%, var(--text));
    }

    .footer a {
      display: inline-block;
      padding: 6px 0;
      color: var(--muted);
      font-weight: 650;
      transition: color var(--dur-1) var(--ease);
    }
    .footer a:hover { color: var(--text); }

    .footer__bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-top: 20px;
      flex-wrap: wrap;
    }

    .tagline { font-weight: 750; color: color-mix(in oklch, var(--muted) 90%, var(--text)); }

    /* Responsive */
    @media (max-width: 980px) {
      .hero__grid { grid-template-columns: 1fr; }
      .hero-art { min-height: 320px; }
      .search { grid-template-columns: 1fr 1fr; }
      .search .btn--submit { grid-column: 1 / -1; }
      .cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .steps { grid-template-columns: 1fr; }
      .quotes { grid-template-columns: 1fr; }
      .app__panel { grid-template-columns: 1fr; }
      .phone { margin: 0; max-width: 520px; }
      .footer__grid { grid-template-columns: 1fr 1fr; }
    }

    @media (max-width: 720px) {
      .nav__links, .actions .btn--ghost { display: none; }
      .hamburger { display: inline-flex; }
      section { padding: 44px 0; }
      .hero { padding: 22px 0 16px; }
      .search-title { flex-direction: column; align-items: flex-start; }
      .search { grid-template-columns: 1fr; }
      .cards { grid-template-columns: 1fr; }
      .stats { grid-template-columns: 1fr; }
      .footer__grid { grid-template-columns: 1fr; }
    }

    @media (prefers-reduced-motion: reduce) {
      * { transition: none !important; scroll-behavior: auto !important; }
    }

    /* Small accessibility helpers */
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    /* Simple toast */
    .toast {
      position: fixed;
      left: 50%;
      bottom: 16px;
      transform: translateX(-50%) translateY(24px);
      opacity: 0;
      pointer-events: none;
      background: color-mix(in oklch, var(--text) 92%, black);
      color: white;
      padding: 12px 14px;
      border-radius: 14px;
      box-shadow: var(--shadow-md);
      transition: opacity var(--dur-2) var(--ease), transform var(--dur-2) var(--ease);
      font-weight: 650;
      max-width: min(560px, calc(100% - 24px));
      text-align: center;
      z-index: 90;
    }
    .toast[data-open="true"] { opacity: 1; transform: translateX(-50%) translateY(0); }
  </style>
</head>

