                <path d="M12 7.2c.4 0 .72.32.72.72v2.86h2.86c.4 0 .72.32.72.72s-.32.72-.72.72h-2.86v2.86c0 .4-.32.72-.72.72s-.72-.32-.72-.72v-2.86H8.42c-.4 0-.72-.32-.72-.72s.32-.72.72-.72h2.86V7.92c0-.4.32-.72.72-.72Z" fill="currentColor"/>
