  <div class="toast" id="toast" role="status" aria-live="polite" data-open="false"></div>

  <script>
    // --- Utilities ---
    const $ = (sel, root = document) => root.querySelector(sel);
    const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

    const toastEl = $('#toast');
    let toastTimer = null;
    function toast(message) {
      if (!toastEl) return;
      toastEl.textContent = message;
      toastEl.dataset.open = 'true';
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        toastEl.dataset.open = 'false';
      }, 2200);
    }

    // --- Mobile drawer (interaction: mobile-menu-toggle) ---
    const openBtn = document.querySelector('[data-open-drawer]');
    const closeEls = document.querySelectorAll('[data-close-drawer]');
    const drawer = document.getElementById('mobile-drawer');

    function setDrawer(open) {
      document.body.classList.toggle('drawer-open', open);
      if (drawer) drawer.setAttribute('aria-hidden', open ? 'false' : 'true');
      if (openBtn) openBtn.setAttribute('aria-expanded', open ? 'true' : 'false');

      if (open) {
        // trap-ish: focus first actionable
        const first = drawer?.querySelector('button, a');
        first?.focus?.();
      } else {
        openBtn?.focus?.();
      }
    }

    openBtn?.addEventListener('click', () => setDrawer(true));
    closeEls.forEach(el => el.addEventListener('click', () => setDrawer(false)));
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        // closes either autocomplete or drawer
        if (document.body.classList.contains('drawer-open')) setDrawer(false);
        closeAutocomplete();
      }
    });

    // --- Smooth scroll helpers ---
    $$('[data-scroll-to]').forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.getAttribute('data-scroll-to');
        const el = target ? document.querySelector(target) : null;
        el?.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    });

    // --- Search focus CTAs ---
    $$('[data-focus-search]').forEach(btn => {
      btn.addEventListener('click', () => {
        setDrawer(false);
        $('#q')?.focus?.();
        $('#search')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      });
    });

    // --- Autocomplete (interaction: search-form) ---
    const qInput = $('#q');
    const ac = $('#ac');
    const acList = $('#ac-list');

    const suggestions = [
      { title: 'Dentist', sub: 'Specialty' },
      { title: 'Primary Care', sub: 'Specialty' },
      { title: 'Dermatologist', sub: 'Specialty' },
      { title: 'Psychiatrist', sub: 'Specialty' },
      { title: 'Eye Doctor', sub: 'Specialty' },
      { title: 'Orthopedic Surgeon', sub: 'Specialty' },
      { title: 'Back pain', sub: 'Condition' },
      { title: 'Annual checkup', sub: 'Visit type' },
      { title: 'Dr. Sarah Chen', sub: 'Provider' },
    ];

    let activeIndex = -1;
    let currentItems = [];

    function openAutocomplete() {
      if (!ac) return;
      ac.dataset.open = 'true';
      qInput?.setAttribute('aria-expanded', 'true');
    }

    function closeAutocomplete() {
      if (!ac) return;
      ac.dataset.open = 'false';
      qInput?.setAttribute('aria-expanded', 'false');
      activeIndex = -1;
      updateActive();
    }

    function renderItems(items) {
      if (!acList) return;
      currentItems = items;
      acList.innerHTML = '';

      if (items.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'ac__item';
        empty.style.cursor = 'default';
        empty.innerHTML = '<div class="ac__main"><div class="ac__title">No matches</div><div class="ac__sub">Try a specialty, condition, or provider name</div></div><span class="kbd">Enter</span>';
        acList.appendChild(empty);
        return;
      }

      items.forEach((it, idx) => {
        const row = document.createElement('div');
        row.className = 'ac__item';
        row.setAttribute('role', 'option');
        row.setAttribute('aria-selected', 'false');
        row.dataset.index = String(idx);
        row.innerHTML = `
          <div class="ac__main">
            <div class="ac__title">${escapeHtml(it.title)}</div>
            <div class="ac__sub">${escapeHtml(it.sub)}</div>
          </div>
          <span class="kbd">Enter</span>
        `;
        row.addEventListener('mouseenter', () => {
          activeIndex = idx;
          updateActive();
        });
        row.addEventListener('mousedown', (e) => {
          // prevent blur
          e.preventDefault();
        });
        row.addEventListener('click', () => {
          chooseIndex(idx);
        });
        acList.appendChild(row);
      });
    }

    function updateActive() {
      const rows = $$('.ac__item[role="option"]', acList);
      rows.forEach((r, i) => r.setAttribute('aria-selected', i === activeIndex ? 'true' : 'false'));
      const activeRow = rows[activeIndex];
      activeRow?.scrollIntoView?.({ block: 'nearest' });
    }

    function chooseIndex(idx) {
      const item = currentItems[idx];
      if (!item || !qInput) return;
      qInput.value = item.title;
      closeAutocomplete();
      toast(`Selected: ${item.title}`);
      // Move focus to location next for momentum
      $('#loc')?.focus?.();
    }

    function escapeHtml(str) {
      return String(str)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    function filterSuggestions(query) {
      const q = query.trim().toLowerCase();
      if (!q) return suggestions.slice(0, 7);
      const starts = [];
      const contains = [];
      for (const s of suggestions) {
        const t = s.title.toLowerCase();
        if (t.startsWith(q)) starts.push(s);
        else if (t.includes(q)) contains.push(s);
      }
      return [...starts, ...contains].slice(0, 7);
    }

    qInput?.addEventListener('input', () => {
      const items = filterSuggestions(qInput.value);
      renderItems(items);
      openAutocomplete();
      activeIndex = items.length ? 0 : -1;
      updateActive();
    });

    qInput?.addEventListener('focus', () => {
      const items = filterSuggestions(qInput.value);
      renderItems(items);
      openAutocomplete();
      if (activeIndex === -1 && items.length) activeIndex = 0;
      updateActive();
    });

    qInput?.addEventListener('blur', () => {
      // Delay so click can register
      setTimeout(() => {
        if (document.activeElement?.closest?.('#field-query')) return;
        closeAutocomplete();
      }, 90);
    });

    qInput?.addEventListener('keydown', (e) => {
      if (ac?.dataset.open !== 'true') return;
      const len = currentItems.length;

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        if (!len) return;
        activeIndex = (activeIndex + 1) % len;
        updateActive();
      }

      if (e.key === 'ArrowUp') {
        e.preventDefault();
        if (!len) return;
        activeIndex = (activeIndex - 1 + len) % len;
        updateActive();
      }

      if (e.key === 'Enter') {
        if (activeIndex >= 0 && len) {
          e.preventDefault();
          chooseIndex(activeIndex);
        }
      }
    });

    // click outside closes autocomplete
    document.addEventListener('click', (e) => {
      if (!ac || ac.dataset.open !== 'true') return;
      const within = e.target?.closest?.('#field-query');
      if (!within) closeAutocomplete();
    });

    // --- Geolocation (best-effort) ---
    const geoBtn = document.querySelector('[data-geo]');
    geoBtn?.addEventListener('click', () => {
      const loc = $('#loc');
      if (!loc) return;
      if (!navigator.geolocation) {
        toast('Geolocation not supported in this browser.');
        return;
      }
      geoBtn.disabled = true;
      geoBtn.textContent = 'Detecting…';
      navigator.geolocation.getCurrentPosition(
        () => {
          // Privacy-respecting placeholder: we won’t reverse geocode offline.
          loc.value = 'Current location';
          toast('Location detected.');
          geoBtn.disabled = false;
          geoBtn.textContent = 'Use my location';
          $('#ins')?.focus?.();
        },
        () => {
          toast('Could not access location.');
          geoBtn.disabled = false;
          geoBtn.textContent = 'Use my location';
        },
        { enableHighAccuracy: false, timeout: 6000, maximumAge: 60_000 }
      );
    });

    // --- Form submit -> search results navigation (in-page mock) ---
    const form = document.getElementById('search-form');
    form?.addEventListener('submit', (e) => {
      e.preventDefault();
      const q = (qInput?.value || '').trim();
      const loc = ($('#loc')?.value || '').trim();
      const ins = ($('#ins')?.value || '').trim();

      const params = new URLSearchParams();
      if (q) params.set('q', q);
      if (loc) params.set('loc', loc);
      if (ins) params.set('ins', ins);

      // No separate results page in this one-page spec.
      // We still "navigate" by updating the hash & showing a toast.
      location.hash = '#search';
      toast(`Searching${q ? ` for “${q}”` : ''}${loc ? ` in ${loc}` : ''}${ins ? ` • ${ins}` : ''}…`);

      // Keep autocomplete closed after submit.
      closeAutocomplete();
    });

    // --- Specialty cards -> filtered search (interaction: specialty-cards) ---
    $$('#specialty-cards [data-specialty]').forEach(card => {
      card.addEventListener('click', (e) => {
        e.preventDefault();
        const specialty = card.getAttribute('data-specialty') || '';
        if (qInput) qInput.value = specialty;
        $('#search')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
        toast(`Showing results for: ${specialty}`);
        $('#loc')?.focus?.();
      });
    });

    // --- Footer anchors referenced in nav (placeholders) ---
    // These keep hash navigation from feeling broken.
    const placeholders = [
      { id: 'help', label: 'Help' },
      { id: 'login', label: 'Log In' },
      { id: 'signup', label: 'Sign Up' },
      { id: 'testimonials', label: 'Testimonials' },
    ];

    placeholders.forEach(p => {
      if (!document.getElementById(p.id)) {
        const s = document.createElement('section');
        s.id = p.id;
        s.style.padding = '0';
        s.setAttribute('aria-label', p.label);
        document.body.appendChild(s);
      }
    });

    // Render initial autocomplete list so the first focus feels instant.
    renderItems(filterSuggestions(''));
  </script>
</body>
